def compute(vars):
    start_shares = vars["v1"]
    end_shares = vars["v2"]
    net_increase = end_shares - start_shares
    return {
        "value": net_increase,
        "trace": {
            "start_shares": start_shares,
            "end_shares": end_shares,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }
